import { useEffect, useState } from 'preact/hooks'
import { store, type State } from '../store.ts'
import { SignIn } from './SignIn.tsx'
import { TeachBar } from './TeachBar.tsx'
import { PageMarks } from './PageMarks.tsx'
import { Editor } from './Editor.tsx'
import { Notes } from './Notes.tsx'
import { Settings } from './Settings.tsx'
import { Messages } from './Messages.tsx'

export function useStore(): State {
  const [, tick] = useState(0)
  useEffect(() => store.subscribe(() => tick((n) => n + 1)), [])
  return store.state
}

export function App() {
  const s = useStore()
  const canTeach = s.staffIds.some((id) => s.sections.some((x) => x.id === id))
  if (!s.embedded) {
    return (
      <div class="frame">
        <header class="hdr"><strong>subjexts</strong></header>
        {s.error && <div class="err" role="alert">{s.error} <button class="link" onClick={() => store.clearError()}>dismiss</button></div>}
        <main class="body">
          <p>This is the panel that books embed. Open a book that has the subjexts line, or use the bookmarklet on the <a href="/" target="_top">home page</a>.</p>
          <SignIn s={s} />
        </main>
      </div>
    )
  }
  return (
    <div class="frame">
      <header class="hdr">
        <button class="icon" title="Close" aria-label="Close the panel" onClick={() => store.openPanel(false)}>✕</button>
        <div class="title">
          <strong>{s.pkg?.title || 'subjexts'}</strong>
          {s.section && !s.teach && <span class="sub">Section {s.section.label}{s.section.course?.code ? ` · ${s.section.course.code}` : ''}</span>}
          {s.teach && <span class="sub teach">Teach mode</span>}
        </div>
        <nav class="tabs" aria-label="Panel views">
          <button class={s.view === 'page' ? 'on' : ''} onClick={() => store.setView('page')}>Page</button>
          {s.session && (canTeach || s.profile?.role !== 'student') && <button class={s.view === 'notes' ? 'on' : ''} onClick={() => store.setView('notes')}>Notes</button>}
          {s.session && <button class={s.view === 'messages' ? 'on' : ''} onClick={() => store.setView('messages')}>Messages</button>}
          <button class={s.view === 'settings' ? 'on' : ''} onClick={() => store.setView('settings')} aria-label="Settings">⚙</button>
        </nav>
      </header>
      {s.error && <div class="err" role="alert">{s.error} <button class="link" onClick={() => store.clearError()}>dismiss</button></div>}
      {s.loading && <div class="loading">Loading…</div>}
      {!s.loading && !s.originOk && s.pkg && (
        <div class="warn">This page's address isn't registered for {s.pkg.slug}. The overlay is read-only here.</div>
      )}
      <main class="body">
        {s.view === 'page' && (
          <>
            {!s.session && <SignIn s={s} />}
            {s.session && canTeach && <TeachBar s={s} />}
            {s.pending && <Editor s={s} />}
            <PageMarks s={s} />
          </>
        )}
        {s.view === 'notes' && <Notes s={s} />}
        {s.view === 'messages' && <Messages s={s} />}
        {s.view === 'settings' && <Settings s={s} />}
      </main>
    </div>
  )
}
